{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([
        {"converted": True}, {"converted": None}, {"converted": False}
    ]) == 1 / 3
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_and_handles_empty_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (10, 10)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3, 4], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = ["\n", "   # comment,with,commas", " a , 1 , 1 ",
             "b, -2, 0", " c, 3,   ", "   "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": -2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no-day,1", "a,1,yes"])
def test_parse_session_log_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", " ", "a,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    original = [
        {"id": "b", "day": 1, "converted": True},
        {"id": "a", "day": 2, "converted": True},
        {"id": "c", "day": 2, "converted": False},
        {"id": "b", "day": 2, "converted": None},
        {"id": "a", "day": 0, "converted": False},
    ]
    assert dedupe_sessions(original) == [original[4], original[3], original[2]]
    assert len(original) == 5
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_range_and_ignores_other_days():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 3, "converted": False},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 3, "converted": False}, {"day": 4, "converted": None}],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "a": [{"converted": True}],
        "b": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [{"converted": None}], "a": [{"converted": True}]}
    rates = conversion_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 1, 0, 2, -1, 3, 4, 5]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
